mapper.select:
select
a.maintenance_id,
a.maintenance_name,
a.device_id,
a.is_valid,
a.maintenance_start,
a.maintenance_stop
from t_device_maintenance a
where 1 = 1
 and a.maintenance_id = #{maintenanceId, jdbcType=BIGINT}
 and a.maintenance_name LIKE CONCAT('%',#{maintenanceName, jdbcType=VARCHAR},'%')
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.is_valid = #{isValid, jdbcType=INTEGER}
 and a.maintenance_start = #{maintenanceStart, jdbcType=TIMESTAMP}
 and a.maintenance_stop = #{maintenanceStop, jdbcType=TIMESTAMP}
 group by a.maintenance_id

